function downloadCsv(rows, filename) {
  const csv = [Object.keys(rows[0] || {}).join(","), ...rows.map((row) => Object.values(row).map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(","))].join("\n");
  const link = document.createElement("a");
  link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  link.download = filename;
  link.click();
  URL.revokeObjectURL(link.href);
}

function Status({ children }) { return <span className={`admin-status ${String(children).toLowerCase().replaceAll(" ", "-")}`}>{children}</span>; }
function Panel({ title, subtitle, action, children, className = "" }) { return <section className={`admin-panel ${className}`}><div className="admin-panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Progress({ value }) { return <div className="admin-progress"><span style={{ width: `${value}%` }} /></div>; }
function MetricCard({ title, value, change, icon: Icon, hint, down = false }) {
  return <article className="admin-metric"><div className="admin-metric-top"><span>{title}</span><i><Icon size={18} /></i></div><strong>{value}</strong><div className="admin-metric-foot"><span className={down ? "negative" : "positive"}>{down ? <ArrowDownRight size={14} /> : <ArrowUpRight size={14} />}{change}</span><small>{hint}</small></div></article>;
}

